/* Scroll-driven reveals for the Wiemer blocks, all CSS. Each class ties an animation to the
   element's own trip through the window (animation-timeline: view()). Browsers without
   scroll-driven animations, and anyone who prefers reduced motion, see everything in place.
   --wiemer-v2-step (0, 1, 2 …) starts an item a little later, for staggered lists.
   Entrances end on `entry` ranges, so they always finish, even in a page's last section. */

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .wiemer-v2-reveal-fade,
    .wiemer-v2-reveal-rise {
      animation-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1);
      animation-fill-mode: both;
      /* the bottom 15 % of the window doesn't count, so things start once they're a little way in */
      animation-timeline: view(block 0% 15%);
      animation-range: entry min(60%, calc(var(--wiemer-v2-step, 0) * 15%)) entry min(100%, calc(40% + var(--wiemer-v2-step, 0) * 15%));
    }
    .wiemer-v2-reveal-fade { animation-name: wiemer-v2-reveal-fade; }
    .wiemer-v2-reveal-rise { animation-name: wiemer-v2-reveal-rise; }

    /* drift: a picture sliding inside its frame for the whole trip through the window */
    .wiemer-v2-reveal-drift {
      animation: wiemer-v2-reveal-drift linear both;
      animation-timeline: view();
      animation-range: cover 0% cover 100%;
    }
  }
}

@keyframes wiemer-v2-reveal-fade {
  from { opacity: 0; }
}
@keyframes wiemer-v2-reveal-rise {
  from { opacity: 0; transform: translateY(var(--wiemer-v2-rise, 25px)); }
}
@keyframes wiemer-v2-reveal-drift {
  from { transform: translateY(var(--wiemer-v2-drift-from, -46px)); }
  to { transform: translateY(var(--wiemer-v2-drift-to, 46px)); }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./wiemer-v2-reveal.css";

/**
 * fade: opacity 0→1 as it comes into view · rise: fade + a 25px lift · drift: a picture
 * sliding inside its frame (parallax), scrubbed for its whole trip through the window
 */
export type WiemerV2RevealEffect = "fade" | "rise" | "drift";

/** The class for an effect, to put straight on an element without a wrapper. */
export function wiemerV2Reveal(effect: WiemerV2RevealEffect) {
  return `wiemer-v2-reveal-${effect}`;
}

/** Inline style: a stagger step (0, 1, 2 …) and, for drift, where it starts and ends in px. */
export function wiemerV2RevealStyle(step = 0, drift?: [number, number]): CSSProperties {
  return {
    "--wiemer-v2-step": step,
    ...(drift && { "--wiemer-v2-drift-from": `${drift[0]}px`, "--wiemer-v2-drift-to": `${drift[1]}px` }),
  } as CSSProperties;
}

export interface WiemerV2RevealProps {
  /** what happens as it enters the window */
  effect?: WiemerV2RevealEffect;
  /** stagger position in a list: each step starts a little later */
  step?: number;
  /** for drift: the vertical offset in px at the start and at the end of the trip */
  drift?: [number, number];
  /** the element to render */
  as?: "div" | "p" | "span" | "li";
  children?: ReactNode;
  className?: string;
}

/** Wraps content in a CSS scroll-driven reveal. Static HTML and old browsers show it in place. */
export function WiemerV2Reveal({ effect = "fade", step = 0, drift, as: Tag = "div", children, className }: WiemerV2RevealProps) {
  return (
    <Tag className={cn(wiemerV2Reveal(effect), className)} style={wiemerV2RevealStyle(step, drift)}>
      {children}
    </Tag>
  );
}
